            if (node.child[ind] == null)
                node.child[ind] = new Trie();

            // go to the next node
            node = node.child[ind];
        }

        // mark the leaf node (end of the word) and store the index of the word in arr[]
        node.index = index;
    }

    /* function for preorder traversal */
    static void Preorder(Trie node, string[] arr)
    {
        if (node == null)
